import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-inv-g2-1/bot.mjs";

const base = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
// Tokyo is UTC+9, no DST. Build instants from local Tokyo wall-clock times.
const tokyo = (iso) => new Date(`${iso}+09:00`);

// Daytime send is allowed, null reason
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo("2026-10-22T12:00:00")), { allowed: true, reason: null });
}
// Quiet start inclusive, end exclusive, wrap across midnight
{
  const g = createPushGate();
  assert.equal(g.attempt(base, tokyo("2026-10-22T22:00:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-23T00:30:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-23T06:59:00")).reason, "quiet_hours");
  assert.equal(g.attempt(base, tokyo("2026-10-23T07:00:00")).allowed, true);
  assert.equal(g.attempt(base, tokyo("2026-10-22T21:59:00")).allowed, true);
}
// Quiet blocks do not consume the daily cap
{
  const g = createPushGate();
  const cap1 = { ...base, dailyCap: 1 };
  for (let i = 0; i < 5; i++) g.attempt(cap1, tokyo("2026-10-22T23:00:00"));
  assert.equal(g.attempt(cap1, tokyo("2026-10-23T08:00:00")).allowed, true);
}
// Cap counts only allowed pushes, per local calendar day
{
  const g = createPushGate();
  assert.equal(g.attempt(base, tokyo("2026-10-22T09:00:00")).allowed, true);
  assert.equal(g.attempt(base, tokyo("2026-10-22T10:00:00")).allowed, true);
  assert.equal(g.attempt(base, tokyo("2026-10-22T11:00:00")).allowed, true);
  assert.equal(g.attempt(base, tokyo("2026-10-22T12:00:00")).reason, "daily_cap_reached");
  // Next local day resets, even though it is only ~13h later
  assert.equal(g.attempt(base, tokyo("2026-10-23T08:00:00")).allowed, true);
}
// Midnight boundary is local, not UTC: 23:30 Tokyo = 14:30 UTC same date
{
  const g = createPushGate();
  const cap1 = { ...base, quietStart: "02:00", quietEnd: "02:00", dailyCap: 1 };
  assert.equal(g.attempt(cap1, tokyo("2026-10-22T23:30:00")).allowed, true);
  assert.equal(g.attempt(cap1, tokyo("2026-10-23T00:10:00")).allowed, true);
}
// Zero cap blocks everything
{
  const g = createPushGate();
  assert.equal(g.attempt({ ...base, dailyCap: 0, quietStart: undefined, quietEnd: undefined }, tokyo("2026-10-22T12:00:00")).reason, "daily_cap_reached");
}
// Quiet hours optional; equal bounds mean none
{
  const g = createPushGate();
  const noQuiet = { id: "u_1", timeZone: "UTC", dailyCap: 5 };
  assert.equal(g.attempt(noQuiet, new Date("2026-10-22T03:00:00Z")).allowed, true);
  const equal = { ...noQuiet, quietStart: "09:00", quietEnd: "09:00" };
  assert.equal(g.attempt(equal, new Date("2026-10-22T09:30:00Z")).allowed, true);
}
// Per-user isolation; per-call settings used
{
  const g = createPushGate();
  const a = { ...base, dailyCap: 1 };
  const b = { ...base, id: "u_2", dailyCap: 1 };
  assert.equal(g.attempt(a, tokyo("2026-10-22T12:00:00")).allowed, true);
  assert.equal(g.attempt(b, tokyo("2026-10-22T12:00:00")).allowed, true);
  assert.equal(g.attempt(a, tokyo("2026-10-22T13:00:00")).reason, "daily_cap_reached");
  assert.equal(g.attempt({ ...a, dailyCap: 2 }, tokyo("2026-10-22T13:00:00")).allowed, true);
}
// Separate gates have independent history
{
  const g1 = createPushGate(), g2 = createPushGate();
  const cap1 = { ...base, dailyCap: 1 };
  g1.attempt(cap1, tokyo("2026-10-22T12:00:00"));
  assert.equal(g2.attempt(cap1, tokyo("2026-10-22T12:00:00")).allowed, true);
}
// DST zone: New York on 2026-11-01 (fall back). Quiet 22:00-07:00 still local.
{
  const g = createPushGate();
  const ny = { id: "u_ny", timeZone: "America/New_York", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
  assert.equal(g.attempt(ny, new Date("2026-11-01T06:30:00Z")).reason, "quiet_hours"); // 01:30 EDT -> still quiet
  assert.equal(g.attempt(ny, new Date("2026-11-01T13:00:00Z")).allowed, true); // 08:00 EST
}
// Invalid inputs throw TypeError
{
  const g = createPushGate();
  const now = tokyo("2026-10-22T12:00:00");
  assert.throws(() => g.attempt({ ...base, timeZone: "Mars/Olympus" }, now), TypeError);
  assert.throws(() => g.attempt({ ...base, quietStart: "25:00" }, now), TypeError);
  assert.throws(() => g.attempt({ ...base, quietEnd: undefined }, now), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: -1 }, now), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: 1.5 }, now), TypeError);
  assert.throws(() => g.attempt(base, new Date("nope")), TypeError);
  assert.throws(() => g.attempt(base, "2026-10-22"), TypeError);
}
// Input not mutated; reasons are distinct snake_case
{
  const g = createPushGate();
  const u = { ...base };
  g.attempt(u, tokyo("2026-10-22T23:00:00"));
  assert.deepEqual(u, base);
}
console.log("all checks passed");
EOF
